const menu=[[Home,"Inicio","home"],[Package,"Productos","products"],[Package,"Categorías","categories"],[ShoppingBag,"Pedidos","orders"],[Users,"Clientes","customers"],[Users,"Equipo","team"],[Boxes,"Inventario","inventory"],[Palette,"Diseño","design"],[Package,"Multimedia","media"],[Ticket,"Marketing","marketing"],[BarChart3,"Analítica","analytics"],[Globe2,"Dominios","domains"],[CreditCard,"Pagos","payments"],[Ticket,"Plan BravoShop","billing"],[Globe2,"Envíos e impuestos","shipping"],[ShieldCheck,"Legal y cumplimiento","legal"],[Settings,"Configuración","settings"]];
export function MerchantAdmin({store,onExit,initialSection="home"}){
	const[section,setSection]=useState(initialSection);
	const[current,setCurrent]=useState(store);
	useEffect(()=>{let alive=true;if(store?.id)loadStore(store.id).then(fresh=>{if(alive)setCurrent(prev=>({...prev,...fresh,role:fresh?.role||prev?.role||store?.role}))}).catch(()=>{});return()=>{alive=false}},[store?.id]);
	const visibleMenu=menu.filter(([, ,key])=>key!=="team"||current.role==="owner"||current.role==="admin");
	let content;
	if(section==="home")content=<HomeView store={current} navigate={setSection}/>;
	else if(section==="products")content=<ProductManager storeId={current?.id} storeSlug={current?.slug} currency={current?.settings?.currency||"EUR"}/>;
	else if(section==="orders")content=<OrdersManager storeId={current?.id}/>;
	else if(section==="customers")content=<CustomersManager storeId={current?.id}/>;
	else if(section==="team")content=<TeamManager store={current}/>;
	else if(section==="inventory")content=<InventoryManager storeId={current?.id} currency={current?.settings?.currency||"EUR"}/>;
	else if(section==="media")content=<MediaLibrary storeId={current?.id}/>;
	else if(section==="design")content=<StoreSettings store={current} mode="design" onSaved={setCurrent}/>;
	else if(section==="payments")content=<Payments store={current}/>;
	else if(section==="billing")content=<PlatformBilling store={current}/>;
	else if(section==="shipping")content=<ShippingTaxes store={current}/>;
	else if(section==="legal")content=<LegalCompliance store={current}/>;
	else if(section==="settings")content=<><StoreSettings store={current} mode="settings" onSaved={setCurrent}/><AccessCode store={current}/></>;
	else if(section==="marketing")content=<MarketingView store={current}/>;
	else if(section==="ai")content=<AiStudio store={current} onMedia={()=>setSection("media")}/>;
	else if(section==="analytics")content=<AnalyticsView store={current}/>;
	else if(section==="domains")content=<DomainsManager store={current}/>;
	else content=<Placeholder section={menu.find(x=>x[2]===section)?.[1]||section}/>;
	return <div className="adminShell"><aside><div className="adminLogo">BravoShop</div><div className="storeSwitch"><small>TIENDA</small><b>{current?.name||"Mi tienda"}</b></div><nav>{visibleMenu.map(([I,t,k])=><button key={k} className={section===k?"active":""} onClick={()=>setSection(k)}><I size={18}/>{t}</button>)}</nav><button className="asideExit" onClick={onExit}>← Volver a BravoShop</button></aside><main className="adminMain">{content}</main></div>
}
function HomeView({store,navigate}){const[data,setData]=useState(null);const[error,setError]=useState("");const[publishing,setPublishing]=useState(false);useEffect(()=>{if(store?.id)getDashboard(store.id).then(setData).catch(e=>setError(e.message))},[store?.id]);const m=data?.metrics||{},o=data?.operations||{};const money=new Intl.NumberFormat(store?.settings?.locale||"es-ES",{style:"currency",currency:store?.settings?.currency||"EUR"});const view=()=>window.open("https://"+store.slug+".bravoshop.online"+(o.published?"":("?studio=1&preview_token="+encodeURIComponent(store.settings?.preview_token||""))),"_blank","noopener,noreferrer");const billingReady=["active","trial"].includes(o.store_status);const readiness=[{label:"Plan BravoShop",ok:billingReady,note:billingReady?(o.store_status==="trial"?"Periodo de prueba vigente":"Suscripción activa"):"Activa un plan para vender",go:"billing"},{label:"Catálogo",ok:o.active_products>0,note:o.active_products?o.active_products+" productos publicados":"Publica al menos un producto",go:"products"},{label:"Diseño",ok:Boolean(store.theme?.template),note:store.theme?.template?"Plantilla configurada":"Elige la apariencia de tu tienda",go:"design"},{label:"Envíos",ok:o.shipping_ready,note:o.shipping_ready?"Zona de envío configurada":"Configura dónde entregas",go:"shipping"},{label:"Información legal",ok:o.legal_ready,note:o.legal_ready?"Datos esenciales completos":"Completa identidad y políticas",go:"legal"},{label:"Pagos",ok:o.payments_ready,note:o.payments_ready?"Cobros habilitados":"Proveedor de cobro pendiente",go:"payments"},{label:"Emails",ok:o.notifications_ready,note:o.notifications_ready?"Confirmaciones transaccionales activas":"Proveedor de email pendiente",go:"settings"}];const done=readiness.filter(x=>x.ok).length;const publicable=Boolean(o.active_products)&&Boolean(store.theme?.template)&&billingReady;const sellReady=publicable&&Boolean(o.shipping_ready)&&Boolean(o.legal_ready)&&Boolean(o.payments_ready)&&Boolean(o.notifications_ready);return <><header><div><small>CENTRO DE OPERACIONES</small><h1>{store?.name||"Tu tienda"}</h1><p className="adminHeaderNote">{o.store_status==="active"?"Tienda activa":o.store_status==="trial"?"Tienda en periodo de prueba":o.store_status==="unpaid"?"Plan vencido o pago pendiente":"Tienda sin publicar"} · {store.slug}.bravoshop.online</p></div><div><button className="ghost" onClick={view}>{o.published?"Ver tienda":"Vista previa"} <ArrowUpRight size={16}/></button><button className={o.published?"ghost danger":""} disabled={publishing||(!o.published&&!sellReady)} onClick={async()=>{setPublishing(true);setError("");try{await setStorePublication(store.id,!o.published);window.location.reload()}catch(e){setError(e.message)}finally{setPublishing(false)}}}>{publishing?"Guardando…":o.published?"Despublicar":"Publicar tienda"}</button><button onClick={()=>navigate("products")}><Plus size={16}/> Producto</button></div></header>{error&&<div className="errorBox">{error}</div>}<section className="metricGrid"><Metric label="Ventas" value={money.format(Number(m.sales||0))} note="Ventas pagadas"/><Metric label="Pedidos pendientes" value={o.pending_orders??0} note="Por preparar o enviar"/><Metric label="Clientes" value={m.customers??0} note="Clientes registrados"/><Metric label="Stock bajo" value={m.low_stock??0} note="Variantes con 3 uds. o menos"/></section><section className="storeLaunchStatus"><article className={publicable?"ready":"pending"}><small>TIENDA PÚBLICA</small><b>{o.published?"Publicada":sellReady?"Lista para publicar":"Configuración pendiente"}</b><span>{o.published?"Tu tienda está visible para clientes.":sellReady?"Todo está preparado; puedes publicarla cuando quieras.":"Completa el checklist para habilitar la publicación."}</span></article><article className={sellReady?"ready":"pending"}><small>VENTA ONLINE</small><b>{sellReady?"Lista para vender":"Aún no lista para cobrar"}</b><span>{sellReady?"Catálogo, envíos, legal y cobros están preparados.":"Completa los puntos pendientes del checklist antes de aceptar pedidos reales."}</span></article></section><section className="adminActionStrip">{o.pending_orders>0&&<button onClick={()=>navigate("orders")}><ShoppingBag size={17}/><span><b>{o.pending_orders} pedidos necesitan atención</b><small>Revisar preparación y envíos</small></span><ArrowUpRight size={15}/></button>}{m.low_stock>0&&<button onClick={()=>navigate("inventory")}><Boxes size={17}/><span><b>{m.low_stock} variantes con stock bajo</b><small>Reponer o permitir venta sin stock</small></span><ArrowUpRight size={15}/></button>}{!o.active_products&&<button onClick={()=>navigate("products")}><Package size={17}/><span><b>Tu catálogo todavía no está publicado</b><small>Crea o publica tu primer producto</small></span><ArrowUpRight size={15}/></button>}</section><section className="operationsGrid"><article className="panel readinessPanel"><div className="panelTitle"><div><small>PREPARACIÓN</small><h3>{done}/{readiness.length} puntos listos</h3></div><div className="readinessRing">{Math.round(done/readiness.length*100)}%</div></div><div className="readinessBar"><i style={{width:(done/readiness.length*100)+"%"}}/></div>{readiness.map(x=><button className="readinessRow" key={x.label} onClick={()=>navigate(x.go)}><span className={x.ok?"ready":"pending"}>{x.ok?"✓":"!"}</span><div><b>{x.label}</b><small>{x.note}</small></div><ArrowUpRight size={15}/></button>)}</article><article className="panel todayPanel"><small>HOY EN TU TIENDA</small><h3>Atención necesaria</h3><button onClick={()=>navigate("orders")}><strong>{o.pending_orders||0}</strong><span>Pedidos por gestionar</span><ArrowUpRight size={15}/></button><button onClick={()=>navigate("inventory")}><strong>{m.low_stock||0}</strong><span>Variantes con stock bajo</span><ArrowUpRight size={15}/></button><button onClick={()=>navigate("products")}><strong>{m.products||0}</strong><span>Productos totales</span><ArrowUpRight size={15}/></button></article><article className="panel recentPanel"><div className="panelTitle"><div><small>ACTIVIDAD</small><h3>Pedidos recientes</h3></div><button className="ghost" onClick={()=>navigate("orders")}>Ver todos</button></div>{data?.recent_orders?.length?data.recent_orders.map(x=><button className="recentOrder" key={x.id} onClick={()=>navigate("orders")}><div><b>#{x.id.slice(0,8)}</b><small>{x.customer_email||"Cliente"}</small></div><span>{money.format(Number(x.total))}</span><em>{String(x.fulfillment_status||x.status||"nuevo").replaceAll("_"," ")}</em></button>):<div className="empty">Aún no hay pedidos. Cuando lleguen, aparecerán aquí.</div>}</article><article className="panel quickPanel"><small>ACCESOS RÁPIDOS</small><h3>Gestiona tu tienda</h3><div className="quickActions">{[["Productos","products"],["Categorías","categories"],["Diseño","design"],["Marketing","marketing"],["Analítica","analytics"],["Inventario","inventory"],["Envíos","shipping"],["Legal","legal"]].map(([label,key])=><button key={key} onClick={()=>navigate(key)}>{label}<ArrowUpRight size={14}/></button>)}</div></article></section></>}
function StoreSettings({store,onSaved,mode="settings"}){const[full,setFull]=useState(null);const[effective,setEffective]=useState({features:[]});const[msg,setMsg]=useState("");const[busy,setBusy]=useState(false);const[device,setDevice]=useState("desktop");const[mediaTarget,setMediaTarget]=useState(null);const[previewKey,setPreviewKey]=useState(0);const previewRef=useRef(null);const[history,setHistory]=useState([]);const[future,setFuture]=useState([]);const[dragId,setDragId]=useState(null);useEffect(()=>{Promise.all([loadStore(store.id),getEffectiveFeatures(store.id)]).then(([x,a])=>{setFull({...x,theme:normalizeTheme(x.theme||{})});setEffective(a||{features:[]})}).catch(e=>setMsg(e.message))},[store.id]);if(!full)return <article className="panel"><p>{msg||"Cargando…"}</p></article>;const settings=full.settings||{},theme=normalizeTheme(full.theme||{}),enabled=(full.features||[]).filter(x=>x.enabled).map(x=>x.feature_key);const patchTheme=next=>setFull(x=>{const before=normalizeTheme(x.theme||{});setHistory(h=>[...h.slice(-29),before]);setFuture([]);return{...x,theme:{...before,...next}}});const undo=()=>{if(!history.length)return;const prev=history[history.length-1];setFuture(f=>[theme,...f]);setHistory(h=>h.slice(0,-1));setFull(x=>({...x,theme:prev}))};const redo=()=>{if(!future.length)return;const next=future[0];setHistory(h=>[...h,theme]);setFuture(f=>f.slice(1));setFull(x=>({...x,theme:next}))};const save=async()=>{setBusy(true);setMsg("");try{await updateStore(store.id,{name:full.name,theme:full.theme,settings:full.settings});if(mode!=="design")await updateStoreFeatures(store.id,enabled);onSaved({...store,name:full.name,settings:full.settings,theme:full.theme});setPreviewKey(x=>x+1);setMsg(mode==="design"?"Diseño guardado y aplicado a la tienda":"Cambios guardados")}catch(e){setMsg(e.message)}finally{setBusy(false)}};const toggle=f=>setFull(x=>({...x,features:[...(x.features||[]).filter(v=>v.feature_key!==f),{feature_key:f,enabled:!enabled.includes(f)}]}));const move=(i,d)=>{const a=[...theme.sections],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];patchTheme({sections:a})};const sectionToggle=id=>patchTheme({sections:theme.sections.map(x=>x.id===id?{...x,visible:!x.visible}:x)});const updateSection=(id,key,value)=>patchTheme({sections:theme.sections.map(x=>x.id===id?{...x,content:{...(x.content||{}),[key]:value}}:x)});const duplicateSection=id=>{const i=theme.sections.findIndex(x=>x.id===id),src=theme.sections[i];if(!src)return;const copy={...src,id:src.type+"-"+Date.now(),label:src.label+" copia",content:{...(src.content||{})}};const a=[...theme.sections];a.splice(i+1,0,copy);patchTheme({sections:a})};const removeSection=id=>patchTheme({sections:theme.sections.filter(x=>x.id!==id)});const dropOn=id=>{if(!dragId||dragId===id)return setDragId(null);const a=[...theme.sections],from=a.findIndex(x=>x.id===dragId),to=a.findIndex(x=>x.id===id);if(from<0||to<0)return;const[item]=a.splice(from,1);a.splice(to,0,item);patchTheme({sections:a});setDragId(null)};const addSection=type=>{const def=ADDABLE_SECTIONS.find(x=>x.type===type);if(!def)return;patchTheme({sections:[...theme.sections,{id:type+"-"+Date.now(),type,label:def.label,visible:true,content:{eyebrow:"",title:def.label,text:"",button:"",button_url:"#catalog",image:""}}]})};useEffect(()=>{if(mode!=="design"||!full)return;const frame=previewRef.current;const send=()=>frame?.contentWindow?.postMessage({type:"BRAVOSHOP_THEME_PREVIEW",theme:normalizeTheme(full.theme||{})},"*");send();const t=setTimeout(send,120);return()=>clearTimeout(t)},[mode,full?.theme,previewKey]);const premiumTemplateAccess=(effective.features||[]).includes("premium_templates");if(mode==="design")return <><header><div><small>BRAVOSHOP DESIGN STUDIO</small><h1>Diseño de tienda</h1></div><div className="designTopActions"><button className="ghost" disabled={!history.length} onClick={undo}>↶ Deshacer</button><button className="ghost" disabled={!future.length} onClick={redo}>↷ Rehacer</button><div className="deviceSwitch"><button className={device==="desktop"?"active":""} onClick={()=>setDevice("desktop")}>Escritorio</button><button className={device==="tablet"?"active":""} onClick={()=>setDevice("tablet")}>Tablet</button><button className={device==="mobile"?"active":""} onClick={()=>setDevice("mobile")}>Móvil</button></div><button disabled={busy} onClick={save}>{busy?"Guardando…":"Guardar y publicar"}</button></div></header><div className="designStudio"><aside className="designControls"><span className="eyebrow">PLANTILLA</span><h2>Elige el punto de partida</h2><div className="templatePicker">{STORE_TEMPLATES.map(t=>{const locked=t.tier==="premium"&&!premiumTemplateAccess;return <button key={t.id} disabled={locked} title={locked?"Requiere plan Premium":""} className={"templateChoice "+(theme.template===t.id?"selected ":"")+(locked?"locked":"")} onClick={()=>!locked&&setFull(x=>({...x,theme:applyTemplate(t.id,x.theme||{})}))}><div className={"templateThumb "+t.id}><i/><i/><i/></div><span><b>{t.name}{t.tier==="premium"&&<em> PREMIUM</em>}</b><small>{locked?"Requiere Premium":t.sector}</small></span></button>})}</div><hr/><span className="eyebrow">ESTILO</span><label>Color principal<input type="color" value={theme.primary_color||"#315b42"} onChange={e=>patchTheme({primary_color:e.target.value})}/></label><label>Estilo tipográfico<select value={theme.font_style||"editorial"} onChange={e=>patchTheme({font_style:e.target.value})}><option value="editorial">Editorial</option><option value="modern">Moderno</option><option value="friendly">Cercano</option></select></label><label>Cabecera<select value={theme.header_style||"clean"} onChange={e=>patchTheme({header_style:e.target.value})}><option value="clean">Limpia</option><option value="floating">Flotante</option><option value="dark">Oscura</option><option value="search">Buscador protagonista</option></select></label><label>Tarjetas de producto<select value={theme.card_style||"soft"} onChange={e=>patchTheme({card_style:e.target.value})}><option value="soft">Suaves</option><option value="minimal">Minimalistas</option><option value="rounded">Redondeadas</option><option value="compact">Compactas</option><option value="tech">Tecnológicas</option></select></label><label>Ancho del contenido<select value={theme.content_width||"wide"} onChange={e=>patchTheme({content_width:e.target.value})}><option value="wide">Amplio</option><option value="contained">Contenido</option><option value="full">Pantalla completa</option></select></label><label>Pie de página<select value={theme.footer_style||"dark"} onChange={e=>patchTheme({footer_style:e.target.value})}><option value="dark">Oscuro</option><option value="light">Claro</option><option value="minimal">Minimalista</option></select></label><label>Columnas de productos<select value={theme.product_columns||3} onChange={e=>patchTheme({product_columns:Number(e.target.value)})}><option value="2">2 columnas</option><option value="3">3 columnas</option><option value="4">4 columnas</option></select></label><hr/><span className="eyebrow">MARCA Y NAVEGACIÓN</span><label>Barra de anuncio<input value={theme.announcement||""} onChange={e=>patchTheme({announcement:e.target.value})} placeholder="Ej. Envío gratis desde 50 €"/></label><label>Logo<div className="imageField"><input value={theme.logo||""} onChange={e=>patchTheme({logo:e.target.value})} placeholder="URL del logo"/><button type="button" className="ghost" onClick={()=>setMediaTarget("__logo")}>Elegir</button></div></label><div className="menuEditor"><b>Menú principal</b>{(theme.menu||[]).map((m,i)=><div className="menuEditorRow" key={i}><input value={m.label} onChange={e=>patchTheme({menu:theme.menu.map((x,j)=>j===i?{...x,label:e.target.value}:x)})}/><input value={m.url} onChange={e=>patchTheme({menu:theme.menu.map((x,j)=>j===i?{...x,url:e.target.value}:x)})}/><button type="button" className="ghost" onClick={()=>patchTheme({menu:theme.menu.filter((_,j)=>j!==i)})}>×</button></div>)}<button type="button" className="ghost" onClick={()=>patchTheme({menu:[...(theme.menu||[]),{label:"Nuevo enlace",url:"#"}]})}>+ Añadir enlace</button></div><hr/><div className="sectionEditorHead"><span><small>ESTRUCTURA</small><b>Secciones de la portada</b></span></div><div className="sectionEditor">{theme.sections.map((x,i)=><details className={"sectionCard "+(!x.visible?"muted":"")} key={x.id} open={x.id==="hero"} draggable onDragStart={()=>setDragId(x.id)} onDragOver={e=>e.preventDefault()} onDrop={()=>dropOn(x.id)}><summary><span className="dragMark">⋮⋮</span><div><b>{x.label}</b><small>{x.type}</small></div><button type="button" onClick={e=>{e.preventDefault();sectionToggle(x.id)}}>{x.visible?"👁":"—"}</button><button type="button" disabled={i===0} onClick={e=>{e.preventDefault();move(i,-1)}}>↑</button><button type="button" disabled={i===theme.sections.length-1} onClick={e=>{e.preventDefault();move(i,1)}}>↓</button></summary><div className="sectionFields"><label>Título<input value={x.content?.title||""} onChange={e=>updateSection(x.id,"title",e.target.value)}/></label><label>Texto<textarea rows="3" value={x.content?.text||""} onChange={e=>updateSection(x.id,"text",e.target.value)}/></label>{["hero","story","imageText","banner"].includes(x.type)&&<><label>Imagen<div className="imageField"><input value={x.content?.image||""} onChange={e=>updateSection(x.id,"image",e.target.value)} placeholder="URL o elige de Multimedia"/><button type="button" className="ghost" onClick={()=>setMediaTarget(x.id)}>Elegir</button></div></label>{x.type==="hero"&&<><label>Posición horizontal <input type="range" min="0" max="100" value={x.content?.image_position_x??50} onChange={e=>updateSection(x.id,"image_position_x",Number(e.target.value))}/></label><label>Posición vertical <input type="range" min="0" max="100" value={x.content?.image_position_y??50} onChange={e=>updateSection(x.id,"image_position_y",Number(e.target.value))}/></label><label>Zoom <input type="range" min="80" max="180" value={x.content?.image_zoom??100} onChange={e=>updateSection(x.id,"image_zoom",Number(e.target.value))}/></label></>}</>}{x.type==="products"&&<label>Número de productos<select value={x.content?.limit||4} onChange={e=>updateSection(x.id,"limit",Number(e.target.value))}><option value="2">2</option><option value="4">4</option><option value="6">6</option><option value="8">8</option><option value="12">12</option></select></label>}<div className="fieldPair"><label>Botón<input value={x.content?.button||""} onChange={e=>updateSection(x.id,"button",e.target.value)}/></label><label>Enlace<input value={x.content?.button_url||""} onChange={e=>updateSection(x.id,"button_url",e.target.value)}/></label></div><div className="sectionActions"><button type="button" className="ghost" onClick={()=>duplicateSection(x.id)}>Duplicar</button>{!["hero","featured"].includes(x.id)&&<button type="button" className="ghost danger" onClick={()=>removeSection(x.id)}>Eliminar</button>}</div></div></details>)}</div><label className="addSectionLabel">Añadir sección<select value="" onChange={e=>{if(e.target.value)addSection(e.target.value)}}><option value="">+ Elegir bloque…</option>{ADDABLE_SECTIONS.map(x=><option key={x.type} value={x.type}>{x.label}</option>)}</select></label></aside><section className="designPreview"><div className={"previewBrowser "+device}><div className="previewBar"><i/><i/><i/><span>{store.slug}.bravoshop.online</span></div><iframe ref={previewRef} key={previewKey} title="Vista previa" src={"https://"+store.slug+".bravoshop.online?preview="+encodeURIComponent(theme.template)+"&studio=1&preview_token="+encodeURIComponent(full.settings?.preview_token||"")}/></div><p>La tienda conserva sus productos y datos; la plantilla cambia únicamente la presentación.</p></section></div>{mediaTarget&&<div className="mediaPickerOverlay"><div className="mediaPickerPanel"><MediaLibrary storeId={store.id} onClose={()=>setMediaTarget(null)} onPick={m=>{if(mediaTarget==="__logo")patchTheme({logo:m.url});else updateSection(mediaTarget,"image",m.url);setMediaTarget(null)}}/></div></div>}{msg&&<div className="successNote">{msg}</div>}</>;return <><header><div><small>BRAVOSHOP ADMIN</small><h1>Configuración</h1></div><button disabled={busy} onClick={save}>{busy?"Guardando…":"Guardar cambios"}</button></header><section className="settingsGrid"><article className="panel formStack"><span className="eyebrow">IDENTIDAD</span><h3>Datos de la tienda</h3><label>Nombre<input value={full.name} onChange={e=>setFull({...full,name:e.target.value})}/></label><label>Descripción corta<textarea rows="3" value={settings.store_description||""} onChange={e=>setFull({...full,settings:{...settings,store_description:e.target.value}})}/></label><label>Email público<input type="email" value={settings.contact_email||""} onChange={e=>setFull({...full,settings:{...settings,contact_email:e.target.value}})}/></label><label>Teléfono público<input value={settings.contact_phone||""} onChange={e=>setFull({...full,settings:{...settings,contact_phone:e.target.value}})}/></label></article><article className="panel formStack"><span className="eyebrow">REGIÓN</span><h3>Mercado principal</h3><div className="fieldPair"><label>Moneda<input value={settings.currency||"EUR"} onChange={e=>setFull({...full,settings:{...settings,currency:e.target.value.toUpperCase().slice(0,3)}})}/></label><label>Idioma / región<input value={settings.locale||"es-ES"} onChange={e=>setFull({...full,settings:{...settings,locale:e.target.value}})}/></label></div><label>País<input maxLength="2" value={settings.country||"ES"} onChange={e=>setFull({...full,settings:{...settings,country:e.target.value.toUpperCase()}})}/></label><label>Zona horaria<input value={settings.timezone||"Europe/Madrid"} onChange={e=>setFull({...full,settings:{...settings,timezone:e.target.value}})}/></label></article><article className="panel formStack"><span className="eyebrow">SEO</span><h3>Cómo aparece tu tienda</h3><label>Título SEO<input value={settings.seo_title||full.name||""} onChange={e=>setFull({...full,settings:{...settings,seo_title:e.target.value}})} maxLength="70"/></label><label>Descripción SEO<textarea rows="4" value={settings.seo_description||""} onChange={e=>setFull({...full,settings:{...settings,seo_description:e.target.value}})} maxLength="170"/></label><div className="seoPreview"><small>{store.slug}.bravoshop.online</small><b>{settings.seo_title||full.name}</b><p>{settings.seo_description||settings.store_description||"Añade una descripción para mejorar la presentación de tu tienda."}</p></div></article><article className="panel"><span className="eyebrow">MÓDULOS</span><h3>Funciones activas</h3><p>Activa únicamente las herramientas que utiliza este comercio.</p><div className="settingsFeatures">{OPERATIVE_FEATURES.map(x=><button key={x} className={"choice "+(enabled.includes(x)?"selected":"")} onClick={()=>toggle(x)} type="button"><strong>{x.replaceAll("_"," ")}</strong><span>{enabled.includes(x)?"Activo":"Inactivo"}</span></button>)}</div><div className="moduleRoadmap settingsRoadmap"><small>PRÓXIMAMENTE</small>{ROADMAP_FEATURES.map(x=><span key={x}>{x.replaceAll("_"," ")} <b>En desarrollo</b></span>)}</div></article></section>{msg&&<div className="successNote">{msg}</div>}</>}
function LegalCompliance({store}){const[full,setFull]=useState(null);const[msg,setMsg]=useState("");const[busy,setBusy]=useState(false);useEffect(()=>{loadStore(store.id).then(setFull).catch(e=>setMsg(e.message))},[store.id]);if(!full)return <article className="panel"><p>{msg||"Cargando información legal…"}</p></article>;const s=full.settings||{};const set=(key,value)=>setFull(x=>({...x,settings:{...(x.settings||{}),[key]:value}}));const required=["legal_name","tax_id","legal_address","legal_email"];const complete=required.filter(k=>String(s[k]||"").trim()).length;const save=async()=>{setBusy(true);setMsg("");try{await updateStore(store.id,{name:full.name,theme:full.theme,settings:full.settings});setMsg("Información legal guardada")}catch(e){setMsg(e.message)}finally{setBusy(false)}};return <><header><div><small>BRAVOSHOP ADMIN</small><h1>Legal y cumplimiento</h1></div><button disabled={busy} onClick={save}>{busy?"Guardando…":"Guardar cambios"}</button></header><div className="complianceStatus"><div><strong>{complete}/4 datos esenciales</strong><span>{complete===4?"Base legal completada":"Completa los datos antes de publicar"}</span></div><div className="complianceBar"><i style={{width:(complete/4*100)+"%"}}/></div></div><div className="legalPreviewLinks"><span>Vista pública:</span>{[["Aviso legal","/aviso-legal"],["Privacidad","/privacidad"],["Cookies","/cookies"],["Envíos","/envios"],["Devoluciones","/devoluciones"]].map(([label,path])=><a key={path} href={"https://"+store.slug+".bravoshop.online"+path} target="_blank" rel="noreferrer">{label} ↗</a>)}</div><section className="legalAdminGrid"><article className="panel formStack"><h3>Identidad del vendedor</h3><p>Estos datos aparecerán en las páginas legales de tu tienda.</p><label>Nombre o razón social<input value={s.legal_name||""} onChange={e=>set("legal_name",e.target.value)} placeholder="Nombre completo o empresa"/></label><label>NIF / CIF / NIE<input value={s.tax_id||""} onChange={e=>set("tax_id",e.target.value)} placeholder="Documento fiscal"/></label><label>Domicilio o establecimiento<input value={s.legal_address||""} onChange={e=>set("legal_address",e.target.value)} placeholder="Dirección completa"/></label><label>Email legal / atención al cliente<input type="email" value={s.legal_email||""} onChange={e=>set("legal_email",e.target.value)} placeholder="legal@tuempresa.com"/></label><label>Teléfono (opcional)<input value={s.legal_phone||""} onChange={e=>set("legal_phone",e.target.value)}/></label></article><article className="panel formStack"><h3>Venta, envíos y devoluciones</h3><label>Plazo general de devolución (días)<input type="number" min="0" value={s.returns_days??14} onChange={e=>set("returns_days",e.target.value)}/></label><label>Información de envíos<textarea rows="5" value={s.shipping_policy||""} onChange={e=>set("shipping_policy",e.target.value)} placeholder="Zonas, plazos y costes de envío"/></label><label>Política de devoluciones<textarea rows="6" value={s.returns_policy||""} onChange={e=>set("returns_policy",e.target.value)} placeholder="Condiciones, excepciones y procedimiento"/></label></article><article className="panel formStack"><h3>Privacidad</h3><label>Contacto de privacidad<input type="email" value={s.privacy_email||s.legal_email||""} onChange={e=>set("privacy_email",e.target.value)}/></label><label>Información adicional<textarea rows="6" value={s.privacy_notes||""} onChange={e=>set("privacy_notes",e.target.value)} placeholder="Información específica sobre tratamientos de datos de tu negocio"/></label><p className="legalHint">BravoShop genera la estructura legal, pero el comerciante debe revisar que la información describa su actividad real.</p></article></section>{msg&&<div className="successNote">{msg}</div>}</>}
function Placeholder({section}){return <><header><div><small>BRAVOSHOP ADMIN</small><h1>{section}</h1></div></header><article className="panel"><h3>{section}</h3><p>Este módulo forma parte de BravoShop y se activará según las funciones y el plan de la tienda.</p></article></>}
function Metric({label,value,note}){return <article className="metric"><small>{label}</small><strong>{value}</strong><p>{note}</p></article>}
function PlatformBilling({store}){
 const[data,setData]=useState(null),[interval,setInterval]=useState("month"),[busy,setBusy]=useState(""),[msg,setMsg]=useState("");
 const load=()=>getBilling(store.id).then(setData).catch(e=>setMsg(e.message));useEffect(()=>{load()},[store.id]);
 const money=(v,currency="EUR")=>new Intl.NumberFormat(store.settings?.locale||"es-ES",{style:"currency",currency}).format(Number(v||0));
 const choose=async plan=>{setBusy(plan.slug);setMsg("");try{const r=await startBillingCheckout(store.id,plan.slug,interval);if(r.url)return window.location.assign(r.url);await load();setMsg("Plan actualizado correctamente")}catch(e){setMsg(e.message)}finally{setBusy("")}};
 const cancel=async()=>{if(!window.confirm("¿Cancelar la renovación al final del periodo actual?"))return;setBusy("cancel");try{await cancelBilling(store.id);await load();setMsg("La suscripción se cancelará al final del periodo")}catch(e){setMsg(e.message)}finally{setBusy("")}};
 const resume=async()=>{setBusy("resume");try{await resumeBilling(store.id);await load();setMsg("Renovación reactivada")}catch(e){setMsg(e.message)}finally{setBusy("")}};
 const portal=async()=>{setBusy("portal");try{const r=await openBillingPortal(store.id);if(r.url)window.location.assign(r.url)}catch(e){setMsg(e.message);setBusy("")}};
 if(!data)return <article className="panel"><p>{msg||"Cargando plan…"}</p></article>;
 const current=data.current,status=current?.status||"sin suscripción",period=current?.current_period_end?new Date(current.current_period_end).toLocaleDateString():"—";
 return <><header><div><small>FACTURACIÓN BRAVOSHOP</small><h1>Plan y suscripción</h1><p className="adminHeaderNote">El cobro de tu plan BravoShop es independiente de Stripe Connect, que utilizas para cobrar a tus propios clientes.</p></div></header>
 {!data.provider_configured&&<div className="setupBanner"><div><b>Facturación pendiente de configuración</b><p>La plataforma todavía no tiene habilitado el proveedor de suscripciones.</p></div></div>}
 {current&&<article className="panel"><div className="panelTitle"><div><small>PLAN ACTUAL</small><h3>{current.plan_name||current.plan_slug||"Acceso especial"}</h3></div><span className={"domainStatus "+(["active","trialing"].includes(status)?"verified":"")}>{status}</span></div><div className="metricGrid compact"><Metric label="Modalidad" value={current.billing_interval==="year"?"Anual":current.billing_interval==="month"?"Mensual":"Especial"}/><Metric label="Próxima fecha" value={period}/><Metric label="Renovación" value={current.cancel_at_period_end?"Se cancelará":"Activa"}/></div>{current.complimentary_reason&&<p>Acceso especial: <b>{current.complimentary_reason}</b></p>}<div className="quickActions">{current.provider_customer_id&&<button className="ghost" disabled={busy==="portal"} onClick={portal}>Gestionar facturas y método de pago</button>}{current.provider_subscription_id&&(current.cancel_at_period_end?<button disabled={busy==="resume"} onClick={resume}>Reactivar renovación</button>:<button className="ghost danger" disabled={busy==="cancel"} onClick={cancel}>Cancelar al final del periodo</button>)}</div></article>}
 <section className="panel"><div className="panelTitle"><div><small>PLANES</small><h3>Elige cómo quieres usar BravoShop</h3></div><div className="deviceSwitch"><button className={interval==="month"?"active":""} onClick={()=>setInterval("month")}>Mensual</button><button className={interval==="year"?"active":""} onClick={()=>setInterval("year")}>Anual</button></div></div><div className="moduleGrid">{(data.plans||[]).map(p=>{const price=interval==="year"?p.annual_price:p.monthly_price,selected=current?.plan_slug===p.slug&&current?.billing_interval===interval;return <article className="panel moduleCard" key={p.id}><span className="eyebrow">{p.slug.toUpperCase()}</span><h3>{p.name}</h3><strong>{price==null?"Precio pendiente":money(price,p.currency||"EUR")}{price!=null&&<small> / {interval==="year"?"año":"mes"}</small>}</strong><p>{p.trial_days>0?p.trial_days+" días de prueba configurados.":"Plan comercial BravoShop."}</p><button disabled={!data.provider_configured||price==null||selected||busy===p.slug} onClick={()=>choose(p)}>{selected?"Plan actual":busy===p.slug?"Procesando…":current?.provider_subscription_id?"Cambiar a este plan":"Contratar plan"}</button></article>})}</div></section>
 {msg&&<div className={msg.includes("correctamente")||msg.includes("reactivada")||msg.includes("cancelará")?"successNote":"errorBox"}>{msg}</div>}</>;
}
function Payments({store}){const[p,setP]=useState(null);const[e,setE]=useState("");const[busy,setBusy]=useState(false);useEffect(()=>{getPaymentAccount(store.id).then(setP).catch(x=>setE(x.message))},[store.id]);const save=async()=>{setBusy(true);setE("");try{await updatePaymentPreferences(store.id,{country:p.country,default_currency:p.default_currency});setP(await getPaymentAccount(store.id));setE("Configuración de pagos guardada")}catch(x){setE(x.message)}finally{setBusy(false)}};return <><header><div><small>BRAVOSHOP ADMIN</small><h1>Pagos</h1></div></header><article className="panel formStack"><h3>Cuenta para recibir tus ventas</h3>{!p?<p>{e||"Cargando…"}</p>:<><label>País de la cuenta<input maxLength="2" value={p.country||""} onChange={x=>setP({...p,country:x.target.value.toUpperCase()})} placeholder="ES, CO, US…"/></label><label>Divisa principal<input maxLength="3" value={p.default_currency||""} onChange={x=>setP({...p,default_currency:x.target.value.toUpperCase()})} placeholder="EUR, COP, USD…"/></label><p>Proveedor: <b>{p.provider==="stripe"?"Stripe Connect":p.provider}</b></p><p>Estado: <b>{p.status==="not_connected"?"No conectada":p.status}</b></p><p>Cobros: <b>{p.charges_enabled?"Habilitados":"Pendientes"}</b> · Transferencias: <b>{p.payouts_enabled?"Habilitadas":"Pendientes"}</b></p><button type="button" disabled={busy} onClick={save}>{busy?"Guardando…":"Guardar país y divisa"}</button><button type="button" disabled={busy} onClick={async()=>{setBusy(true);setE("");try{const r=await connectPaymentAccount(store.id);window.location.assign(r.url)}catch(x){setE(x.message);setBusy(false)}}}>{p.provider_account_id?"Continuar configuración de Stripe":"Conectar con Stripe"}</button><button className="ghost" type="button" onClick={async()=>{setBusy(true);try{await syncPaymentAccount(store.id);setP(await getPaymentAccount(store.id));setE("Estado de Stripe actualizado")}catch(x){setE(x.message)}finally{setBusy(false)}}}>Actualizar estado</button><p>La conexión bancaria se realizará mediante onboarding seguro del proveedor; BravoShop no almacenará datos bancarios.</p></>}{e&&p&&<p>{e}</p>}</article></>}

function CategoriesManager({store}){const[items,setItems]=useState([]),[name,setName]=useState(""),[description,setDescription]=useState(""),[msg,setMsg]=useState(""),[editing,setEditing]=useState(null);const load=()=>listCategories(store.id).then(setItems).catch(e=>setMsg(e.message));useEffect(()=>{load()},[store.id]);const add=async()=>{if(!name.trim())return;try{await createCategory(store.id,{name,description,position:items.length});setName("");setDescription("");await load()}catch(e){setMsg(e.message)}};const move=async(i,d)=>{const j=i+d;if(j<0||j>=items.length)return;const a=items[i],b=items[j];await Promise.all([updateCategory(store.id,a.id,{position:b.position}),updateCategory(store.id,b.id,{position:a.position})]);load()};const saveEdit=async()=>{if(!editing?.name?.trim())return;try{await updateCategory(store.id,editing.id,{name:editing.name.trim(),description:editing.description||""});setEditing(null);await load();setMsg("Categoría actualizada")}catch(e){setMsg(e.message)}};return <><header><div><small>CATÁLOGO</small><h1>Categorías</h1><p className="adminHeaderNote">Organiza el catálogo para navegación, filtros y secciones de la tienda.</p></div></header><section className="categoryWorkspace"><article className="panel formStack"><span className="eyebrow">NUEVA CATEGORÍA</span><h3>Crea una colección navegable</h3><label>Nombre<input value={name} onChange={e=>setName(e.target.value)} placeholder="Plantas de interior"/></label><label>Descripción<textarea rows="4" value={description} onChange={e=>setDescription(e.target.value)} placeholder="Descripción opcional"/></label><button onClick={add}>Crear categoría</button>{msg&&<div className="errorBox">{msg}</div>}</article><article className="panel"><div className="panelTitle"><div><small>ORGANIZACIÓN</small><h3>{items.length} categorías</h3></div></div>{items.length?items.map((x,i)=><div className="categoryRow" key={x.id}><div className="categoryHandle">⋮⋮</div><div><b>{x.name}</b><small>/{x.slug} · {x.product_count||0} productos</small></div><span className={"catalogStatus "+(x.active?"active":"draft")}>{x.active?"Visible":"Oculta"}</span><div><button className="ghost" onClick={()=>setEditing({id:x.id,name:x.name,description:x.description||""})}>Editar</button><button className="ghost" onClick={()=>move(i,-1)} disabled={!i}>↑</button><button className="ghost" onClick={()=>move(i,1)} disabled={i===items.length-1}>↓</button><button className="ghost" onClick={async()=>{await updateCategory(store.id,x.id,{active:!x.active});load()}}>{x.active?"Ocultar":"Mostrar"}</button><button className="ghost danger" onClick={async()=>{if(window.confirm("¿Eliminar esta categoría? Los productos no se eliminarán.")){await deleteCategory(store.id,x.id);load()}}}>Eliminar</button></div></div>):<div className="empty">Todavía no has creado categorías.</div>}</article></section>{editing&&<div className="modal"><article className="panel formStack"><h3>Editar categoría</h3><label>Nombre<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})}/></label><label>Descripción<textarea rows="4" value={editing.description} onChange={e=>setEditing({...editing,description:e.target.value})}/></label><div className="quickActions"><button className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button onClick={saveEdit}>Guardar cambios</button></div></article></div>}</>}
function MarketingView({store}){
 const blank={code:"",kind:"percent",value:10,minimum_amount:0,usage_limit:"",starts_at:"",ends_at:""};
 const[items,setItems]=useState([]),[subscribers,setSubscribers]=useState([]),[abandoned,setAbandoned]=useState([]),[form,setForm]=useState(blank),[editing,setEditing]=useState(null),[msg,setMsg]=useState("");
 const load=()=>Promise.all([listDiscounts(store.id),listNewsletterSubscribers(store.id),listAbandonedCheckouts(store.id)]).then(([d,s,a])=>{setItems(d);setSubscribers(s);setAbandoned(a)}).catch(e=>setMsg(e.message));useEffect(()=>{load()},[store.id]);
 const create=async()=>{setMsg("");try{await createDiscount(store.id,{...form,value:Number(form.value),minimum_amount:Number(form.minimum_amount||0),usage_limit:form.usage_limit===""?null:Number(form.usage_limit),starts_at:form.starts_at||null,ends_at:form.ends_at||null});setForm(blank);await load();setMsg("Código creado")}catch(e){setMsg(e.message)}};
 const edit=x=>setEditing({...x,value:String(x.value??""),minimum_amount:String(x.minimum_amount??0),usage_limit:x.usage_limit??"",starts_at:x.starts_at?new Date(x.starts_at).toISOString().slice(0,16):"",ends_at:x.ends_at?new Date(x.ends_at).toISOString().slice(0,16):""});
 const save=async()=>{setMsg("");try{await updateDiscount(store.id,editing.id,{code:editing.code,kind:editing.kind,value:Number(editing.value),minimum_amount:Number(editing.minimum_amount||0),usage_limit:editing.usage_limit===""?null:Number(editing.usage_limit),starts_at:editing.starts_at||null,ends_at:editing.ends_at||null,active:Boolean(editing.active)});setEditing(null);await load();setMsg("Descuento actualizado")}catch(e){setMsg(e.message)}};
 const activeSubscribers=subscribers.filter(x=>x.status==="active");
 return <><header><div><small>CRECIMIENTO</small><h1>Marketing</h1></div></header><section className="marketingGrid"><article className="panel formStack"><span className="eyebrow">DESCUENTOS</span><h3>Crear código promocional</h3><label>Código<input value={form.code} onChange={e=>setForm({...form,code:e.target.value.toUpperCase()})} placeholder="BIENVENIDA10"/></label><div className="fieldPair"><label>Tipo<select value={form.kind} onChange={e=>setForm({...form,kind:e.target.value})}><option value="percent">Porcentaje</option><option value="fixed">Importe fijo</option></select></label><label>Valor<input type="number" min="0.01" step=".01" value={form.value} onChange={e=>setForm({...form,value:e.target.value})}/></label></div><label>Compra mínima<input type="number" min="0" step=".01" value={form.minimum_amount} onChange={e=>setForm({...form,minimum_amount:e.target.value})}/></label><div className="fieldPair"><label>Empieza<input type="datetime-local" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></label><label>Termina<input type="datetime-local" value={form.ends_at} onChange={e=>setForm({...form,ends_at:e.target.value})}/></label></div><label>Límite de usos<input type="number" min="1" value={form.usage_limit} onChange={e=>setForm({...form,usage_limit:e.target.value})} placeholder="Sin límite"/></label><button onClick={create}>Crear descuento</button></article><article className="panel"><span className="eyebrow">NEWSLETTER</span><h3>{activeSubscribers.length} suscriptores activos</h3><p>Solo aparecen personas que dieron consentimiento desde la tienda. Una baja no puede reactivarse desde Admin.</p><div className="newsletterAdminList">{subscribers.slice(0,12).map(x=><div className="health" key={x.id}><div><b>{x.email}</b><small>{x.status==="active"?"Consentimiento: "+new Date(x.consent_at).toLocaleDateString():"Baja: "+new Date(x.unsubscribed_at||x.updated_at).toLocaleDateString()}</small></div>{x.status==="active"?<button className="ghost danger" onClick={async()=>{try{await unsubscribeNewsletterSubscriber(store.id,x.id);await load();setMsg("Suscriptor dado de baja")}catch(e){setMsg(e.message)}}}>Dar de baja</button>:<em>Baja</em>}</div>)}{!subscribers.length&&<div className="empty">Todavía no hay suscriptores.</div>}</div></article></section>
 {editing&&<article className="panel formStack"><div className="panelTitle"><div><small>EDITAR DESCUENTO</small><h3>{editing.code}</h3></div><button className="ghost" onClick={()=>setEditing(null)}>Cancelar</button></div><label>Código<input value={editing.code} onChange={e=>setEditing({...editing,code:e.target.value.toUpperCase()})}/></label><div className="fieldPair"><label>Tipo<select value={editing.kind} onChange={e=>setEditing({...editing,kind:e.target.value})}><option value="percent">Porcentaje</option><option value="fixed">Importe fijo</option></select></label><label>Valor<input type="number" min="0.01" step=".01" value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value})}/></label></div><label>Compra mínima<input type="number" min="0" step=".01" value={editing.minimum_amount} onChange={e=>setEditing({...editing,minimum_amount:e.target.value})}/></label><div className="fieldPair"><label>Empieza<input type="datetime-local" value={editing.starts_at} onChange={e=>setEditing({...editing,starts_at:e.target.value})}/></label><label>Termina<input type="datetime-local" value={editing.ends_at} onChange={e=>setEditing({...editing,ends_at:e.target.value})}/></label></div><label>Límite de usos<input type="number" min="1" value={editing.usage_limit} onChange={e=>setEditing({...editing,usage_limit:e.target.value})} placeholder="Sin límite"/></label><label className="switchRow"><span>Activo</span><input type="checkbox" checked={Boolean(editing.active)} onChange={e=>setEditing({...editing,active:e.target.checked})}/></label><button onClick={save}>Guardar descuento</button></article>}
 <article className="panel"><h3>Códigos promocionales</h3>{items.length?items.map(x=><div className="discountRow" key={x.id}><div><b>{x.code}</b><small>{x.kind==="percent"?x.value+"%":x.value+" "+(store.settings?.currency||"EUR")} · mínimo {x.minimum_amount||0} · {x.usage_count||0}{x.usage_limit?"/"+x.usage_limit:""} usos</small></div><span className={"domainStatus "+(x.active?"verified":"")}>{x.active?"Activo":"Pausado"}</span><div><button className="ghost" onClick={()=>edit(x)}>Editar</button><button className="ghost" onClick={async()=>{await toggleDiscount(store.id,x.id,!x.active);load()}}>{x.active?"Pausar":"Activar"}</button><button className="ghost danger" onClick={async()=>{if(window.confirm("¿Eliminar este descuento?")){await deleteDiscount(store.id,x.id);if(editing?.id===x.id)setEditing(null);load()}}}>Eliminar</button></div></div>):<div className="empty">Todavía no has creado códigos de descuento.</div>}</article>
 <article className="panel"><span className="eyebrow">AUTOMATIZACIONES</span><h3>Recuperación de carrito</h3><p>Los recordatorios se generan automáticamente solo cuando el cliente dio consentimiento expreso durante el checkout.</p><div className="moduleRoadmap"><span>Checkouts con consentimiento <b>{abandoned.length}</b></span><span>Recordatorios enviados/encolados <b>{abandoned.filter(x=>x.recovery_notified_at).length}</b></span><span>Campañas <b>En desarrollo</b></span><span>Tarjetas regalo <b>En desarrollo</b></span></div>{abandoned.slice(0,6).map(x=><div className="health" key={x.id}><div><b>{x.customer_email}</b><small>{Number(x.total).toFixed(2)} {x.currency} · caducó {new Date(x.expires_at).toLocaleString()}</small></div><em>{x.recovery_notified_at?"Recordatorio":"Pendiente"}</em></div>)}</article>{msg&&<div className={/creado|actualizado|baja/i.test(msg)?"successNote":"errorBox"}>{msg}</div>}</>;
}
function AnalyticsView({store}){const[data,setData]=useState(null);const[msg,setMsg]=useState("");useEffect(()=>{getAnalytics(store.id).then(setData).catch(e=>setMsg(e.message))},[store.id]);if(!data)return <article className="panel"><p>{msg||"Calculando analítica real…"}</p></article>;const m=data.metrics||{},money=new Intl.NumberFormat(store?.settings?.locale||"es-ES",{style:"currency",currency:store?.settings?.currency||"EUR"}),max=Math.max(1,...data.daily.map(x=>Number(x.sales||0)));return <><header><div><small>ÚLTIMOS 30 DÍAS</small><h1>Analítica</h1></div></header><section className="metricGrid"><Metric label="Ventas" value={money.format(m.sales||0)} note="Ingresos pagados"/><Metric label="Pedidos" value={m.orders||0} note="Pedidos del periodo"/><Metric label="Ticket medio" value={money.format(m.average_order||0)} note="Promedio por pedido"/><Metric label="Clientes recurrentes" value={m.repeat_customers||0} note="Compraron más de una vez"/></section><section className="analyticsLayout"><article className="panel analyticsChart"><div className="panelTitle"><div><small>VENTAS DIARIAS</small><h3>Rendimiento del mes</h3></div><span>{money.format(m.sales||0)}</span></div><div className="salesBars">{data.daily.map((d,i)=><div className="salesDay" key={d.day} title={d.day+" · "+money.format(d.sales)}><i style={{height:Math.max(3,d.sales/max*100)+"%"}}/><small>{i%5===0?d.day.slice(8):""}</small></div>)}</div></article><article className="panel"><h3>Estado de pedidos</h3>{data.order_statuses.length?data.order_statuses.map(x=><div className="insightRow" key={x.status}><span>{String(x.status).replaceAll("_"," ")}</span><b>{x.value}</b></div>):<div className="empty">Aún no hay pedidos.</div>}</article><article className="panel wideAnalytics"><h3>Productos que más venden</h3>{data.top_products.length?data.top_products.map((x,i)=><div className="topProductRow" key={x.title}><span>{i+1}</span><div><b>{x.title}</b><small>{x.units} unidades</small></div><strong>{money.format(x.revenue)}</strong></div>):<div className="empty">Cuando haya ventas, aquí aparecerán tus productos destacados.</div>}</article></section></>}
function DomainsManager({store}){const[domains,setDomains]=useState([]);const[hostname,setHostname]=useState("");const[pending,setPending]=useState(null);const[msg,setMsg]=useState("");const[busy,setBusy]=useState("");const load=()=>listDomains(store.id).then(setDomains).catch(e=>setMsg(e.message));useEffect(()=>{load()},[store.id]);const add=async()=>{if(!hostname.trim())return;setMsg("");try{const r=await addDomain(store.id,hostname.trim());setPending(r.verification);setHostname("");await load()}catch(e){setMsg(e.message)}};const verify=async id=>{setMsg("");setBusy(id);try{const r=await verifyDomain(store.id,id);setPending(null);await load();setMsg(r.activation?.configured?"Propiedad verificada. Añade ahora los registros DNS de Railway que aparecen abajo.":"Propiedad verificada. La activación automática en Railway aún no está configurada.")}catch(e){await load();setMsg(e.message)}finally{setBusy("")}};const sync=async id=>{setMsg("");setBusy(id);try{const r=await syncDomain(store.id,id);await load();setMsg(r.domain?.infrastructure_status==="active"?"Dominio activo con SSL.":"Estado actualizado. Railway todavía está esperando DNS o certificado.")}catch(e){setMsg(e.message)}finally{setBusy("")}};const remove=async id=>{if(!window.confirm("¿Quitar este dominio de la tienda?"))return;setBusy(id);try{await removeDomain(store.id,id);await load()}catch(e){setMsg(e.message)}finally{setBusy("")}};const label=d=>d.infrastructure_status==="active"?"Activo con SSL":d.infrastructure_status==="certificate_pending"?"DNS válido · SSL pendiente":d.infrastructure_status==="dns_pending"?"DNS de Railway pendiente":d.infrastructure_status==="error"?"Error de activación":d.status==="verified"?"Propiedad verificada · activación pendiente":"Pendiente de verificación";return <><header><div><small>PUBLICACIÓN</small><h1>Dominios</h1></div><a className="ghost" href={"https://"+store.slug+".bravoshop.online"} target="_blank" rel="noreferrer">Abrir tienda <ArrowUpRight size={16}/></a></header><section className="domainGrid"><article className="panel"><span className="eyebrow">DOMINIO BRAVOSHOP</span><h3>{store.slug}.bravoshop.online</h3><p>Incluido con tu tienda y disponible como dirección principal o temporal.</p><span className="domainStatus verified">Activo</span></article><article className="panel"><span className="eyebrow">DOMINIO PROPIO</span><h3>Conecta tu marca</h3><p>Añade un dominio que controles. BravoShop verifica la propiedad y prepara su activación HTTPS en Railway.</p><div className="domainAdd"><input value={hostname} onChange={e=>setHostname(e.target.value.toLowerCase())} placeholder="www.mitienda.com"/><button onClick={add}>Añadir</button></div></article></section>{pending&&<article className="panel dnsCard"><h3>1. Verifica la propiedad</h3><p>Añade este registro TXT en tu proveedor DNS y después pulsa verificar.</p><div><small>HOST</small><code>{pending.hostname}</code></div><div><small>VALOR</small><code>{pending.value}</code></div></article>}<article className="panel"><h3>Dominios conectados</h3>{domains.length?domains.map(d=><div className="domainRow domainRowExpanded" key={d.id}><div><b>{d.hostname}</b><small>{label(d)}</small>{Array.isArray(d.dns_records)&&d.dns_records.length>0&&<div className="domainDnsRecords"><strong>DNS para activar Railway</strong>{d.dns_records.map((r,i)=><div className="dnsRecord" key={i}><span>{r.recordType||"DNS"} · {r.purpose==="ownership"?"Verificación":"Tráfico"}</span><code>{r.hostlabel||d.hostname}</code><code>{r.requiredValue}</code><em>{r.status||"PENDING"}</em></div>)}{d.certificate_status&&<small>SSL: {d.certificate_status}</small>}</div>}</div><span className={"domainStatus "+(d.infrastructure_status==="active"?"verified":d.status)}>{d.infrastructure_status==="active"?"active":d.status}</span><div>{d.status!=="verified"&&<button className="ghost" disabled={busy===d.id} onClick={()=>verify(d.id)}>Verificar propiedad</button>}{d.status==="verified"&&d.infrastructure_status!=="active"&&<button className="ghost" disabled={busy===d.id} onClick={()=>sync(d.id)}>Comprobar activación</button>}<button className="ghost danger" disabled={busy===d.id} onClick={()=>remove(d.id)}>Quitar</button></div></div>):<div className="empty">Todavía no has añadido un dominio propio.</div>}{msg&&<div className={/activo|verificada|actualizado/i.test(msg)?"successNote":"errorBox"}>{msg}</div>}</article></>}
function ModuleHub({title,cards}){return <><header><div><small>BRAVOSHOP ADMIN</small><h1>{title}</h1></div></header><section className="moduleGrid">{cards.map(([name,desc])=><article className="panel moduleCard" key={name}><span className="moduleDot"/><h3>{name}</h3><p>{desc}</p><button className="ghost" type="button">Configurar</button></article>)}</section></>}

function AiStudio({store,onMedia}){const[prompt,setPrompt]=useState("");const[access,setAccess]=useState({features:[],entitlements:[],plan:null});useEffect(()=>{getEffectiveFeatures(store.id).then(setAccess).catch(()=>setAccess({features:[],entitlements:[],plan:null}))},[store.id]);const lifetime=(access.entitlements||[]).some(x=>x.feature_key==="ai_images"&&x.permanent);const entitled=(access.features||[]).includes("ai_images");return <><header><div><small>BRAVOSHOP AI</small><h1>Estudio de imágenes</h1></div><button className="ghost" onClick={onMedia}>Abrir Multimedia</button></header><section className="aiStudio"><article className="panel aiComposer"><span className="eyebrow">GENERADOR VISUAL</span><h2>Crea imágenes para tu tienda</h2>{lifetime&&<div className="aiAccessBadge">✓ IA activada de por vida</div>}{entitled&&!lifetime&&<div className="aiAccessBadge">✓ Acceso IA activo</div>}{!entitled&&<div className="setupBanner"><div><b>Función Premium</b><p>Activa Premium o canjea un código especial en Configuración.</p></div><span>Premium</span></div>}{entitled&&access.plan?.slug==="premium"&&!lifetime&&<div className="aiAccessBadge">✓ Incluido en Premium</div>}<p>Describe el producto, escena o banner que necesitas. Las imágenes generadas se guardarán en la biblioteca de esta tienda.</p><textarea rows="6" placeholder="Ej.: fotografía editorial de una mochila de cuero sobre fondo cálido, luz natural…" value={prompt} onChange={e=>setPrompt(e.target.value)}/><div className="aiOptions"><button className="choice selected" type="button"><strong>Producto</strong><small>Catálogo limpio</small></button><button className="choice" type="button"><strong>Editorial</strong><small>Campañas y portada</small></button><button className="choice" type="button"><strong>Social</strong><small>Contenido promocional</small></button></div><button disabled={!entitled} title={!entitled?"Requiere acceso Premium o código especial":"Proveedor de imágenes pendiente de conexión"}>Generar imagen</button><small className="aiPending">Proveedor de imágenes pendiente de conexión</small></article><article className="panel aiPreview"><div className="aiPreviewCanvas"><Brain size={38}/><b>La imagen aparecerá aquí</b><span>Después podrás guardarla en Multimedia y usarla en productos, banners o campañas.</span></div><div className="aiChecklist"><b>Flujo preparado</b><span>1. Escribir prompt</span><span>2. Generar</span><span>3. Revisar resultado</span><span>4. Guardar en Multimedia</span></div></article></section></>}

function AccessCode({store}){const[code,setCode]=useState("");const[msg,setMsg]=useState("");const[items,setItems]=useState([]);const refresh=()=>getEntitlements(store.id).then(setItems).catch(()=>{});useEffect(refresh,[store.id]);const redeem=async()=>{setMsg("");try{const r=await redeemAccessCode(store.id,code);setMsg(r.permanent?"Acceso permanente activado":"Código activado");setCode("");refresh()}catch(e){setMsg(e.message)}};return <article className="panel accessCodePanel"><span className="eyebrow">CÓDIGOS BRAVOSHOP</span><h3>Canjear acceso especial</h3><p>Introduce un código concedido por BravoShop para activar funciones Premium en esta tienda.</p><div className="accessCodeRow"><input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="BRAVO-XXXX"/><button disabled={!code.trim()} onClick={redeem}>Canjear</button></div>{msg&&<p className="accessMessage">{msg}</p>}{items.length>0&&<div className="entitlementList">{items.map((x,i)=><div className="health" key={x.feature_key+i}><b>{x.feature_key.replaceAll("_"," ")}</b><em>{x.permanent?"De por vida":"Activo"}</em></div>)}</div>}</article>}

function ShippingTaxes({store}){
 const[zones,setZones]=useState([]),[tax,setTax]=useState({enabled:false,prices_include_tax:true,default_rate:0}),[zone,setZone]=useState({name:"España",countries:"ES"}),[rate,setRate]=useState({name:"Envío estándar",price:"",free_over:"",min_days:"",max_days:""}),[zoneEdit,setZoneEdit]=useState(null),[rateEdit,setRateEdit]=useState(null),[msg,setMsg]=useState("");
 const load=()=>Promise.all([getShipping(store.id),getTaxSettings(store.id)]).then(([z,t])=>{setZones(z);setTax(t)}).catch(e=>setMsg(e.message));useEffect(()=>{load()},[store.id]);
 const addZone=async()=>{try{await createShippingZone(store.id,{name:zone.name,countries:zone.countries.split(",").map(x=>x.trim()).filter(Boolean)});setMsg("Zona creada");load()}catch(e){setMsg(e.message)}};
 const addRate=async id=>{try{await createShippingRate(store.id,id,{name:rate.name,price:Number(rate.price||0),free_over:rate.free_over===""?null:Number(rate.free_over),min_days:rate.min_days===""?null:Number(rate.min_days),max_days:rate.max_days===""?null:Number(rate.max_days)});setRate({name:"Envío estándar",price:"",free_over:"",min_days:"",max_days:""});setMsg("Tarifa creada");load()}catch(e){setMsg(e.message)}};
 const saveZone=async()=>{try{await updateShippingZone(store.id,zoneEdit.id,{name:zoneEdit.name,countries:String(zoneEdit.countries||"").split(",").map(x=>x.trim()).filter(Boolean),active:Boolean(zoneEdit.active)});setZoneEdit(null);setMsg("Zona actualizada");load()}catch(e){setMsg(e.message)}};
 const saveRate=async()=>{try{await updateShippingRate(store.id,rateEdit.id,{name:rateEdit.name,price:Number(rateEdit.price||0),free_over:rateEdit.free_over===""?null:Number(rateEdit.free_over),min_days:rateEdit.min_days===""?null:Number(rateEdit.min_days),max_days:rateEdit.max_days===""?null:Number(rateEdit.max_days),active:Boolean(rateEdit.active)});setRateEdit(null);setMsg("Tarifa actualizada");load()}catch(e){setMsg(e.message)}};
 const saveTax=async()=>{try{setTax(await updateTaxSettings(store.id,{enabled:tax.enabled,prices_include_tax:tax.prices_include_tax,default_rate:Number(tax.default_rate||0)}));setMsg("Impuestos guardados")}catch(e){setMsg(e.message)}};
 return <><header><div><small>LOGÍSTICA</small><h1>Envíos e impuestos</h1></div></header><section className="adminGrid"><article className="panel formStack"><h3>Zonas de envío</h3><label>Nombre<input value={zone.name} onChange={e=>setZone({...zone,name:e.target.value})}/></label><label>Países (ISO, separados por coma)<input value={zone.countries} onChange={e=>setZone({...zone,countries:e.target.value.toUpperCase()})} placeholder="ES, PT, FR"/></label><button onClick={addZone}>Crear zona</button>
 {zones.map(z=><div className="health" key={z.id}><div><b>{z.name}</b><small>{(z.countries||[]).join(", ")} · {z.active?"Activa":"Pausada"}</small>{(z.rates||[]).map(r=><div className="shippingRateRow" key={r.id}><small>{r.name}: {r.price}{r.free_over?" · gratis desde "+r.free_over:""}{r.min_days||r.max_days?" · "+(r.min_days||"?")+"–"+(r.max_days||"?")+" días":""} · {r.active?"Activa":"Pausada"}</small><span><button className="ghost" onClick={()=>setRateEdit({...r,price:String(r.price??""),free_over:r.free_over??"",min_days:r.min_days??"",max_days:r.max_days??""})}>Editar</button><button className="ghost" onClick={async()=>{await updateShippingRate(store.id,r.id,{active:!r.active});load()}}>{r.active?"Pausar":"Activar"}</button><button className="ghost danger" onClick={async()=>{if(window.confirm("¿Eliminar esta tarifa?")){await deleteShippingRate(store.id,r.id);if(rateEdit?.id===r.id)setRateEdit(null);load()}}}>Eliminar</button></span></div>)}</div><div className="shippingZoneActions"><button className="ghost" onClick={()=>setZoneEdit({id:z.id,name:z.name,countries:(z.countries||[]).join(", "),active:z.active})}>Editar zona</button><button className="ghost" onClick={async()=>{await updateShippingZone(store.id,z.id,{active:!z.active});load()}}>{z.active?"Pausar zona":"Activar zona"}</button><button className="ghost danger" onClick={async()=>{if(window.confirm("¿Eliminar esta zona y todas sus tarifas?")){await deleteShippingZone(store.id,z.id);if(zoneEdit?.id===z.id)setZoneEdit(null);load()}}}>Eliminar zona</button></div></div>)}
 <hr/><h3>Nueva tarifa</h3><label>Nombre<input value={rate.name} onChange={e=>setRate({...rate,name:e.target.value})}/></label><div className="fieldPair"><label>Precio<input type="number" min="0" step=".01" value={rate.price} onChange={e=>setRate({...rate,price:e.target.value})}/></label><label>Gratis desde<input type="number" min="0" step=".01" value={rate.free_over} onChange={e=>setRate({...rate,free_over:e.target.value})}/></label></div><div className="fieldPair"><label>Días mín.<input type="number" min="0" step="1" value={rate.min_days} onChange={e=>setRate({...rate,min_days:e.target.value})}/></label><label>Días máx.<input type="number" min="0" step="1" value={rate.max_days} onChange={e=>setRate({...rate,max_days:e.target.value})}/></label></div>{zones.map(z=><button className="ghost" key={z.id} onClick={()=>addRate(z.id)}>Añadir a {z.name}</button>)}</article><article className="panel formStack"><h3>Impuestos</h3><label className="switchRow"><span>Calcular impuestos</span><input type="checkbox" checked={Boolean(tax.enabled)} onChange={e=>setTax({...tax,enabled:e.target.checked})}/></label><label className="switchRow"><span>Los precios ya incluyen impuestos</span><input type="checkbox" checked={Boolean(tax.prices_include_tax)} onChange={e=>setTax({...tax,prices_include_tax:e.target.checked})}/></label><label>Tipo general (%)<input type="number" min="0" max="100" step="0.01" value={tax.default_rate??0} onChange={e=>setTax({...tax,default_rate:e.target.value})}/></label><button onClick={saveTax}>Guardar impuestos</button><p>BravoShop aplicará esta configuración al cálculo del checkout. El comerciante es responsable de configurar el tratamiento fiscal que corresponda a su actividad y jurisdicción.</p></article></section>
 {zoneEdit&&<article className="panel formStack"><div className="panelTitle"><div><small>EDITAR ZONA</small><h3>{zoneEdit.name}</h3></div><button className="ghost" onClick={()=>setZoneEdit(null)}>Cancelar</button></div><label>Nombre<input value={zoneEdit.name} onChange={e=>setZoneEdit({...zoneEdit,name:e.target.value})}/></label><label>Países<input value={zoneEdit.countries} onChange={e=>setZoneEdit({...zoneEdit,countries:e.target.value.toUpperCase()})}/></label><label className="switchRow"><span>Activa</span><input type="checkbox" checked={Boolean(zoneEdit.active)} onChange={e=>setZoneEdit({...zoneEdit,active:e.target.checked})}/></label><button onClick={saveZone}>Guardar zona</button></article>}
 {rateEdit&&<article className="panel formStack"><div className="panelTitle"><div><small>EDITAR TARIFA</small><h3>{rateEdit.name}</h3></div><button className="ghost" onClick={()=>setRateEdit(null)}>Cancelar</button></div><label>Nombre<input value={rateEdit.name} onChange={e=>setRateEdit({...rateEdit,name:e.target.value})}/></label><div className="fieldPair"><label>Precio<input type="number" min="0" step=".01" value={rateEdit.price} onChange={e=>setRateEdit({...rateEdit,price:e.target.value})}/></label><label>Gratis desde<input type="number" min="0" step=".01" value={rateEdit.free_over} onChange={e=>setRateEdit({...rateEdit,free_over:e.target.value})}/></label></div><div className="fieldPair"><label>Días mín.<input type="number" min="0" step="1" value={rateEdit.min_days} onChange={e=>setRateEdit({...rateEdit,min_days:e.target.value})}/></label><label>Días máx.<input type="number" min="0" step="1" value={rateEdit.max_days} onChange={e=>setRateEdit({...rateEdit,max_days:e.target.value})}/></label></div><label className="switchRow"><span>Activa</span><input type="checkbox" checked={Boolean(rateEdit.active)} onChange={e=>setRateEdit({...rateEdit,active:e.target.checked})}/></label><button onClick={saveRate}>Guardar tarifa</button></article>}
 {msg&&<div className={msg.includes("creada")||msg.includes("actualizada")||msg.includes("guardados")?"successNote":"errorBox"}>{msg}</div>}</>;
}

